        session.slots.propertyId = undefined;
        session.slots.interestedPropertyId = undefined;
        session.slots.lastGhostEb = eb;
        routeLog(chatId, text, 'GHOST:fast');
          pushHistory(session, { role: 'user', text }, this.cfg.maxHistory);
